tw.local.parameters = new tw.object.listOf.toolkit.TWSYS.SQLParameter();
tw.local.parameters[0] = new tw.object.toolkit.TWSYS.SQLParameter();
tw.local.parameters[0].value = "operationType";

tw.local.results = new tw.object.listOf.NameValuePair()
var productCode = tw.local.operationCodeConditions[0];
var requestType =tw.local.operationCodeConditions[1];
var operationCode = tw.local.operationCodeConditions[2];
var counter = 0;

if (tw.local.records && tw.local.records.listLength > 0) {
	tw.local.isSuccessful = true;
	for (var i=0; i<tw.local.records.listLength; i++) {
	if (requestType=="amend" && operationCode=="COL") {
		if (productCode =="OUBC" && (tw.local.records[i]["CODE"]=="COL" || tw.local.records[i]["CODE"] == "DIS")) {
			tw.local.results[counter] = new tw.object.NameValuePair();
			tw.local.results[counter].name = tw.local.records[i]["NAME"] || "";
			tw.local.results[counter].value = tw.local.records[i]["CODE"] || "";
			counter++;
		}
		else if (productCode =="OSBC" && (tw.local.records[i]["CODE"]=="COL" || tw.local.records[i]["CODE"] == "PUR")) {
			tw.local.results[counter] = new tw.object.NameValuePair();
			tw.local.results[counter].name = tw.local.records[i]["NAME"] || "";
			tw.local.results[counter].value = tw.local.records[i]["CODE"] || "";
			counter++;
		}
		else if (productCode =="OMBC" && (tw.local.records[i]["CODE"]=="COL" || tw.local.records[i]["CODE"] == "DIS")) {
			tw.local.results[counter] = new tw.object.NameValuePair();
			tw.local.results[counter].name = tw.local.records[i]["NAME"] || "";
			tw.local.results[counter].value = tw.local.records[i]["CODE"] || "";
			counter++;
		}
		
	}
	
	else{
		tw.local.results[i] = new tw.object.NameValuePair();
		tw.local.results[i].name = tw.local.records[i]["NAME"] || "";
		tw.local.results[i].value = tw.local.records[i]["CODE"] || "";
		}
	}
}

